# Check harness state for submission status
import rlm.harness as harness

try:
    overview = harness.overview()
    print("Harness overview:")
    for key, val in overview.items():
        print(f"  {key}: {val}")
except Exception as e:
    print(f"Error getting overview: {e}")

print("\nTrying to list all memories...")
memories = [h for h in harness.list_memories()]
for m in memories[:10]:
    print(f"Memory: {m['id']} - {m.get('content', '')[:50]}...")

# Get harness state snapshot to see current status
from rlm import get_harness_state
state = get_harness_state()

print("Snapshot of current state:")
snapshot = state.snapshot()
if isinstance(snapshot, dict):
    print("\nKeys in snapshot:", list(snapshot.keys())[:15])

    # Look for task or attempt-related info
    for key in ['task', 'task_status', 'attempts', 'current_task', 'instance_id']:
        if key in snapshot:
            print(f"\n{key}: {snapshot[key]}")
elif hasattr(snapshot, '__iter__'):
    print("\nSnapshot appears iterable")
else:
    print(f"\nSnapshot type: {type(snapshot)}")

# Also try listing entries
print("\n\nListing harness entries...")
try:
    entries = state.list()
    print(f"Number of entries: {len(entries)}")
    for entry in entries[:5]:
        print(f"  {entry}")
except Exception as e:
    print(f"Error listing entries: {e}")

# Check current attempt count and status more carefully
from rlm import get_harness_state, list_subagents

state = get_harness_state()

# Try to find attempt-related information in the entries
print("Checking all entries for attempt info...")
entries = state.list()
for entry in entries:
    print(f"\nEntry: {entry['id']} ({entry.get('kind', '')})")
    if isinstance(entry.get('content'), str) and len(entry['content']) > 100:
        content_preview = entry['content'][:200] + "..."
        print(f"  Preview: {content_preview}")

    # Look for metadata with attempt info
    if 'metadata' in entry:
        print(f"  Metadata keys: {list(entry['metadata'].keys())}")
        if 'attempt_count' in entry.get('metadata', {}):
            print(f"  Attempt count: {entry['metadata']['attempt_count']}")

# Check global memories too  
print("\n\nGlobal entries:")
try:
    global_entries = state.scope.entries.get() if hasattr(state.scope, 'entries') else []
    for e in global_entries[:5]:
        print(f"  Global: {e}")
except Exception as e:
    print(f"  Error: {e}")

# List subagents 
print("\n\nSubagents:")
try:
    subagents = list_subagents()
    for sa in subagents:
        print(f"  Subagent: {sa}")
except Exception as e:
    print(f"  Error listing subagents: {e}")

# Check current attempt count and status more carefully - fixed iteration
from rlm import get_harness_state, list_subagents

state = get_harness_state()

print("Checking all entries for attempt info...")
entries = state.list()
for entry in entries:
    print(f"\nEntry ID: {entry.id} ({entry.kind})")
    if hasattr(entry.content, '__len__') and len(str(entry.content)) > 100:
        content_preview = str(entry.content)[:200] + "..."
        print(f"  Content preview: {content_preview}")

    # Look for metadata with attempt info  
    if hasattr(entry.metadata, 'get'):
        print(f"  Metadata keys: {list(entry.metadata.keys())}")
        if hasattr(entry.metadata, 'get') and entry.metadata.get('attempt_count', None) is not None:
            try:
                ac = int(entry.metadata.get('attempt_count', 0))
                print(f"  Attempt count: {ac}")
            except:
                pass
    else:
        if isinstance(entry.get('metadata', {}), dict):
            print(f"  Metadata: {entry['metadata']}")
            print(f"  Attempt count from metadata: {entry['metadata'].get('attempt_count')}")

# List subagents 
print("\n\nSubagents:")
try:
    subagents = list_subagents()
    for sa in subagents[:5]:
        print(f"  Subagent: {sa}")
except Exception as e:
    print(f"  Error listing subagents: {e}")

